<template><section class="panel" aria-labelledby="pricing-diff-title"><h2 id="pricing-diff-title">{{ t('publicPricingAdmin.diffTitle') }}</h2><p>{{ t('publicPricingAdmin.generationMeta',{draft:draft?.revision??'—',live:live?.release?.version??'—'}) }}</p><div class="table-wrap"><table><thead><tr><th>{{t('publicModelsAdmin.modelKey')}}</th><th>{{t('publicPricingAdmin.liveInput')}}</th><th>{{t('publicPricingAdmin.draftInput')}}</th><th>{{t('publicPricingAdmin.liveOutput')}}</th><th>{{t('publicPricingAdmin.draftOutput')}}</th><th>{{t('publicPricingAdmin.visibility')}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.modelKey" :class="{changed:row.changed}"><td><code>{{row.modelKey}}</code></td><td>{{price(row.liveInput)}}</td><td>{{price(row.draftInput)}}</td><td>{{price(row.liveOutput)}}</td><td>{{price(row.draftOutput)}}</td><td>{{row.priceVisibility}}</td></tr><tr v-if="!rows.length"><td colspan="6">{{t('publicPricingAdmin.empty')}}</td></tr></tbody></table></div></section></template>
<script setup>import{computed}from'vue';import{useI18n}from'@/composables/useI18n';const props=defineProps({draft:Object,live:Object});const{t}=useI18n();const rows=computed(()=>{const live=new Map((props.live?.items??[]).map(x=>[x.modelKey,x])),draft=new Map((props.draft?.models??[]).map(x=>[x.model_key,x]));return[...new Set([...draft.keys(),...live.keys()])].sort().map(modelKey=>{const next=draft.get(modelKey),old=live.get(modelKey);const row={modelKey,liveInput:old?.inputPriceUsdPerMillionTokens??null,draftInput:next?.input_price_usd_per_million_tokens??null,liveOutput:old?.outputPriceUsdPerMillionTokens??null,draftOutput:next?.output_price_usd_per_million_tokens??null,priceVisibility:old?.priceVisibility??'draft'};row.changed=!next||!old||row.liveInput!==row.draftInput||row.liveOutput!==row.draftOutput;return row})});const price=v=>v===null||v===undefined?t('publicModelsAdmin.notSet'):`$${v}`</script>
<style scoped>.panel{background:var(--el-bg-color);border:1px solid var(--el-border-color);border-radius:16px;padding:20px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:760px}th,td{text-align:left;padding:10px;border-bottom:1px solid var(--el-border-color)}.changed{background:var(--el-color-warning-light-9)}code{font-family:ui-monospace,monospace}</style>
